import docx
from doc_helpers import add_p, add_h1, add_h2, add_h3

def build_intro(doc):
    add_h1(doc, "MỞ ĐẦU")

    add_h2(doc, "1. Lý do chọn đề tài")
    add_p(doc, "Ngành dịch vụ ăn uống và nhà hàng (Food and Beverage - F&B) đóng vai trò là một trong những trụ cột kinh tế dịch vụ năng động và có tốc độ tăng trưởng nhanh nhất tại Việt Nam. Theo Báo cáo thị trường Kinh doanh Ẩm thực tại Việt Nam, quy mô thị trường F&B Việt Nam liên tục mở rộng với doanh thu hàng trăm nghìn tỷ đồng, nhưng đi liền với đó là áp lực cạnh tranh khốc liệt, chi phí thuê mặt bằng đắt đỏ và chi phí nhân công không ngừng leo thang [1]. Điều này đòi hỏi các nhà quản trị ẩm thực phải tìm kiếm những giải pháp đổi mới sáng tạo nhằm tối ưu hóa chi phí vận hành, triệt tiêu lãng phí nguyên vật liệu và nâng cao chất lượng dịch vụ khách hàng.")

    add_p(doc, "Trong mô hình vận hành nhà hàng truyền thống, phần lớn các công đoạn phục vụ vẫn dựa trên quy trình thủ công mang tính rời rạc. Nhân viên phục vụ sử dụng sổ ghi chép để ghi nhận món ăn từ thực khách tại bàn, sau đó di chuyển bộ xuống khu vực bếp để chuyển giao order giấy. Quy trình này bộc lộ vô số bất cập nghiêm trọng: thời gian truyền đạt thông tin kéo dài dẫn đến khách hàng phải chờ đợi lâu; chữ viết tay khó đọc hoặc sai sót trong quá trình ghi chú (như ghi nhầm định lượng, quên các yêu cầu đặc biệt về dị ứng thực phẩm, độ cay, mức đá/đường); sự thiếu hụt kết nối thời gian thực khiến nhân viên phục vụ không nắm bắt được món nào đã hết nguyên liệu để kịp thời tư vấn cho khách, gây ra tình trạng thực khách gọi món xong lại phải đổi món nhiều lần.")

    add_p(doc, "Hơn thế nữa, tại khu vực nhà bếp (Back of House), việc sử dụng máy in vé giấy nhiệt truyền thống bộc lộ nhiều điểm nghẽn kỹ thuật: giấy in dễ bị rách, ướt, mờ chữ do dầu mỡ và nhiệt độ cao trong môi trường bếp; đầu bếp không thể có cái nhìn tổng quan về thứ tự ưu tiên các đơn hàng đang chờ, dẫn đến tình trạng các món vào trước nhưng lại được chế biến sau, gây bức xúc cho khách hàng. Nghiêm trọng hơn, khi khách hàng muốn hủy món hoặc đổi món, thông tin thường không được đồng bộ tức thì xuống bếp, dẫn đến việc món ăn đã chế biến xong nhưng không có người nhận, gây lãng phí nguyên vật liệu và tổn thất tài chính trực tiếp cho nhà hàng theo các khảo sát thực tế ngành dịch vụ F&B [2].")

    add_p(doc, "Về phương diện thanh toán và kế toán dòng tiền, sự phát triển bùng nổ của thanh toán không dùng tiền mặt, đặc biệt là mạng lưới chuyển khoản liên ngân hàng nhanh qua mã phản hồi nhanh VietQR (chuẩn NAPAS 247) [3], đã định hình lại thói quen chi tiêu của người tiêu dùng. Tuy nhiên, phần lớn các phần mềm quản lý nhà hàng hiện nay chỉ dừng lại ở mức hiển thị mã QR tĩnh (khách hàng phải tự nhập số tiền và nội dung chuyển khoản) hoặc yêu cầu thu ngân phải kiểm tra thủ công ứng dụng ngân hàng trên điện thoại cá nhân để xác nhận tiền về. Điều này tạo ra rủi ro gian lận rất lớn thông qua các hình thức biên lai chuyển tiền giả (fake bill), gây tắc nghẽn quầy thu ngân trong giờ cao điểm và gây thất thoát dòng tiền mà ban quản lý không thể kiểm soát.")

    add_p(doc, "Mặt khác, các giải pháp phần mềm quản trị nhà hàng thương mại phổ biến trên thị trường hiện nay (như KiotViet, CukCuk, iPOS.vn) tuy đã có những đóng góp nhất định nhưng vẫn tồn tại nhiều hạn chế về mặt kiến trúc: đa phần phụ thuộc vào phần mềm cài đặt cục bộ (Desktop Client) trên hệ điều hành Windows, gây khó khăn cho việc triển khai linh hoạt trên các thiết bị di động hay máy tính bảng; cơ chế đồng bộ dữ liệu giữa các máy trạm thường sử dụng giao thức HTTP Polling định kỳ (3 - 5 giây/lần), gây tải nặng cho máy chủ và có độ trễ lớn; việc tách biệt giữa hệ thống bán hàng tại quầy (POS) và hệ thống gọi món tự phục vụ (Self-ordering QR) khiến dữ liệu bị phân mảnh, không thể đồng bộ tức thời trạng thái bàn ăn và lượng tồn kho.")

    add_p(doc, "Xuất phát từ những trăn trở và yêu cầu thực tiễn cấp bách nói trên, đề tài \"Xây dựng Hệ thống Quản lý Nhà hàng Full Web đa phân hệ (POS, KDS, BOH Admin và QR Ordering)\" đã được đề xuất và thực hiện. Đề tài hướng tới việc xây dựng một giải pháp phần mềm quản trị nhà hàng thuần Web toàn diện, hiện đại, vận hành trên nền tảng .NET 9 và Blazor Server, tích hợp SignalR cho khả năng giao tiếp thời gian thực hai chiều, kết hợp quy trình thanh toán tự động VietQR/SePay Webhook và thuật toán định lượng trừ kho tự động (BOM). Giải pháp này hứa hẹn sẽ giải quyết triệt để các bất cập trong chu trình phục vụ ăn uống, mang lại hiệu quả kinh tế rõ rệt và nâng tầm trải nghiệm cho cả thực khách lẫn đội ngũ vận hành nhà hàng.")

    add_h2(doc, "2. Mục đích nghiên cứu của đề tài")
    add_p(doc, "Mục tiêu tổng quát của đề tài là nghiên cứu, thiết kế và phát triển thành công một hệ sinh thái phần mềm quản lý nhà hàng ẩm thực thuần Web hoàn chỉnh, có khả năng vận hành ổn định trên mọi nền tảng thiết bị (máy tính để bàn, laptop, máy tính bảng, điện thoại di động) thông qua trình duyệt web mà không đòi hỏi cài đặt ứng dụng phức tạp.")

    add_p(doc, "Để hiện thực hóa mục tiêu tổng quát, đề tài tập trung giải quyết các mục tiêu cụ thể sau:")
    add_p(doc, "1. Nghiên cứu nghiệp vụ và chuẩn hóa kiến trúc Clean Architecture: Phân tách rõ ràng các ranh giới kiến trúc phần mềm giữa tầng miền nghiệp vụ (Domain), tầng ứng dụng (Application), tầng hạ tầng truy xuất dữ liệu (Infrastructure) và tầng biểu diễn giao diện (Presentation). Đảm bảo mã nguồn có tính module hóa cao, dễ bảo trì, dễ mở rộng và độc lập hoàn toàn với các framework bên ngoài.", indent=0.7)
    add_p(doc, "2. Xây dựng Phân hệ Bán hàng (Point of Sale - POS) chuyên nghiệp: Quản lý sơ đồ bàn ăn trực quan theo khu vực tầng; hỗ trợ đầy đủ quy trình phục vụ ăn tại bàn (Dine-in) và bán mang đi (Takeaway); tích hợp menu món, gói combo, tùy chọn modifier (Size, Topping, đường đá); cung cấp các nghiệp vụ bàn nâng cao (chuyển bàn, gộp bàn, tách hóa đơn); quản lý ca làm việc, kiểm soát dòng tiền két (Till-in, Till-out) và xuất hóa đơn nhiệt K80.", indent=0.7)
    add_p(doc, "3. Xây dựng Phân hệ Màn hình Nhà bếp (Kitchen Display System - KDS) thời gian thực: Thay thế máy in order giấy bằng màn hình kỹ thuật số hiển thị vé món (Tickets) tự động cập nhật qua SignalR; hỗ trợ phân loại món ăn theo các trạm chế biến chuyên biệt (Kitchen Stations: Bếp Pizza, Bếp Chiên, Quầy Bar Pha Chế); theo dõi tiến độ nấu nướng (Pending -> Processing -> Done); cảnh báo vi phạm thời gian phục vụ (SLA Alerts); cung cấp giao diện gom món tổng hợp (Aggregate Batching).", indent=0.7)
    add_p(doc, "4. Xây dựng Phân hệ Khách hàng Tự gọi món (QR Ordering): Thiết kế giao diện Mobile-first tối ưu cho trình duyệt điện thoại; tự động nhận diện bàn ăn qua mã QR an toàn; cho phép khách hàng tự chọn món, chọn combo, tùy biến topping và gửi đơn trực tiếp lên quầy thu ngân; hỗ trợ theo dõi trực tiếp trạng thái nấu nướng trong bếp và tự động đồng bộ phiên khi đổi bàn ăn.", indent=0.7)
    add_p(doc, "5. Xây dựng Phân hệ Quản trị Hậu sảnh (Back of House - BOH Admin): Cung cấp các công cụ quản lý chuyên sâu về Thực đơn, Bảng định mức nguyên vật liệu (BOM Recipe), Quản lý kho hàng (Nhập kho, Kiểm kê cân bằng tồn); Trung tâm phê duyệt yêu cầu nhạy cảm (Approval Center); Đối soát ca thu ngân và thanh toán; Hệ thống báo cáo phân tích kinh doanh đa chiều (Doanh thu, Món bán chạy, Hao hụt lãng phí hủy món).", indent=0.7)
    add_p(doc, "6. Tích hợp Hệ thống Khách hàng thân thiết (Loyalty & CRM): Tự động tích lũy điểm thưởng theo giá trị hóa đơn; áp dụng tiêu điểm trừ tiền mặt; hỗ trợ danh mục đổi điểm lấy món thưởng; tự động chiết khấu theo hạng thẻ thành viên; bảo đảm cơ chế hoàn trả điểm (Rollback) an toàn khi giao dịch bị hủy.", indent=0.7)
    add_p(doc, "7. Hiện thực hóa Tự động hóa Thanh toán VietQR và Webhook SePay: Sinh mã VietQR động theo đơn hàng; tự động lắng nghe và xác thực chữ ký HMAC từ Webhook ngân hàng; cập nhật trạng thái đơn hàng và in hóa đơn K80 ngay tức khắc mà không cần nhân viên can thiệp thủ công.", indent=0.7)

    add_h2(doc, "3. Đối tượng và phạm vi nghiên cứu")
    add_p(doc, "3.1. Đối tượng nghiên cứu")
    add_p(doc, "• Đối tượng nghiệp vụ: Chu trình vận hành khép kín của mô hình nhà hàng ẩm thực hiện đại, bao gồm luồng giao dịch tiền sảnh (Front of House), quy trình chế biến hậu sảnh (Back of House), luồng chuỗi cung ứng tồn kho và quy trình kế toán đối soát dòng tiền thu ngân.")
    add_p(doc, "• Đối tượng công nghệ: Nền tảng Microsoft .NET 9 và ngôn ngữ lập trình C# 13; kiến trúc ứng dụng web tương tác Blazor Server; cơ chế truyền thông điệp thời gian thực SignalR Core; hệ quản trị cơ sở dữ liệu quan hệ Microsoft SQL Server cùng Entity Framework Core 9; các giải pháp bảo mật nhận thực JWT Bearer, băm mật khẩu/mã PIN BCrypt và giao thức tích hợp Open Banking qua Webhook SePay.")

    add_p(doc, "3.2. Phạm vi nghiên cứu")
    add_p(doc, "• Phạm vi về không gian: Áp dụng nghiên cứu và thử nghiệm thực tế cho mô hình nhà hàng dịch vụ ăn uống quy mô vừa và lớn, có kết cấu phân tầng nhiều khu vực, bao gồm cả không gian phục vụ tại chỗ (Dine-in) và quầy phục vụ mang đi (Takeaway).")
    add_p(doc, "• Phạm vi về chức năng: Nghiên cứu chuyên sâu và bao phủ toàn diện 70 chức năng nghiệp vụ chuẩn hóa thuộc 5 phân hệ: Điểm bán hàng (POS), Màn hình bếp (KDS), Quản trị hậu cần (BOH Admin), Tự gọi món tại bàn (QR Ordering) và Hệ thống tài khoản phân quyền thành viên (Account & Loyalty).")
    add_p(doc, "• Phạm vi về công nghệ: Hệ thống được xây dựng thuần Web (Full Web Architecture), toàn bộ giao diện vận hành trên trình duyệt hiện đại (Chrome, Edge, Safari, Firefox), sử dụng hạ tầng kết nối mạng nội bộ (Local LAN) kết hợp Internet bảo mật qua HTTPS và WebSocket.")
    add_p(doc, "• Phạm vi về thời gian: Đề tài được triển khai nghiên cứu, phân tích, thiết kế, lập trình và thực nghiệm kiểm thử trong năm 2026.")

    add_h2(doc, "4. Ý nghĩa khoa học và thực tiễn của đề tài")
    add_p(doc, "4.1. Ý nghĩa khoa học")
    add_p(doc, "• Đề tài đóng góp một mô hình mẫu về việc ứng dụng kiến trúc Clean Architecture đa tầng vào bài toán doanh nghiệp phức tạp có sự kết hợp chặt chẽ giữa tương tác Web truyền thống và truyền thông điệp thời gian thực (Real-time Event-Driven Architecture).")
    add_p(doc, "• Làm sáng tỏ phương pháp giải quyết các bài toán xung đột dữ liệu phân tán trong môi trường nhà hàng: giải quyết xung đột khi khách hàng gọi món và thu ngân chỉnh sửa đơn đồng thời (Optimistic Concurrency Control qua RowVersion); giải quyết bài toán trừ kho định lượng tự động đa tầng (BOM Deduction) đảm bảo tính Idempotent; giải quyết bài toán bảo toàn chi phí nguyên vật liệu khi hủy món ăn đã chế biến (Cancellation Waste Management).")
    add_p(doc, "• Khẳng định tính hiệu quả vượt trội của công nghệ Blazor Server kết hợp Circuit State trong việc xây dựng các phần mềm quản trị nghiệp vụ có mật độ tương tác cao, giúp thống nhất toàn bộ ngôn ngữ phát triển (C#) từ tầng cơ sở dữ liệu lên đến tầng giao diện người dùng.")

    add_p(doc, "4.2. Ý nghĩa thực tiễn")
    add_p(doc, "• Đối với thực khách: Mang lại trải nghiệm ẩm thực hiện đại, chủ động và tiện lợi. Khách hàng có thể tự do khám phá thực đơn hình ảnh bắt mắt, tự chọn topping theo sở thích cá nhân, theo dõi tiến độ chế biến món ăn minh bạch và thanh toán không tiền mặt siêu tốc, xóa bỏ hoàn toàn cảm giác sốt ruột chờ đợi.")
    add_p(doc, "• Đối với nhân viên nhà hàng: Giảm tải đáng kể áp lực công việc cho nhân viên phục vụ trong giờ cao điểm; triệt tiêu các lỗi sai sót do ghi chép bằng tay; giúp đầu bếp nhận lệnh chế biến tức thì, phân loại trạm rõ ràng và gom món khoa học; giúp thu ngân đối soát két tiền ca làm việc chính xác tuyệt đối, tránh thất thoát tiền mặt.")
    add_p(doc, "• Đối với chủ nhà hàng và ban quản lý: Cung cấp một công cụ quản trị tập trung, nắm bắt tình hình doanh thu, tồn kho và công suất phục vụ theo thời gian thực tại bất kỳ đâu; kiểm soát chặt chẽ giá vốn hàng bán (COGS); giảm thiểu hao hụt thất thoát nguyên liệu nhờ công thức định lượng chuẩn hóa; kiểm soát các hành vi gian lận thông qua cơ chế phê duyệt nhạy cảm (Approval Center) và nhật ký kiểm toán (Audit Logs) minh bạch.")

    add_h2(doc, "5. Bố cục của đồ án tốt nghiệp")
    add_p(doc, "Bản thuyết minh Đồ án tốt nghiệp được cấu trúc thành các chương chính theo đúng hướng dẫn quy chế đào tạo đại học của Bộ Giáo dục & Đào tạo [4] và quy định đồ án tốt nghiệp của Trường Đại học Phenikaa [5]:")
    add_p(doc, "• MỞ ĐẦU: Giới thiệu tính cấp thiết, lý do chọn đề tài, mục tiêu, đối tượng, phạm vi nghiên cứu, ý nghĩa khoa học, ý nghĩa thực tiễn và bố cục của báo cáo.", indent=0.7)
    add_p(doc, "• CHƯƠNG 1: TỔNG QUAN TÀI LIỆU VÀ CƠ SỞ LÝ LUẬN VỀ HỆ THỐNG QUẢN LÝ NHÀ HÀNG. Trình bày tổng quan về chu trình vận hành F&B, vai trò các phân hệ, phân tích so sánh các giải pháp hiện có trên thị trường và tổng quan nền tảng công nghệ áp dụng (.NET 9, Blazor Server, SignalR, EF Core 9, VietQR).", indent=0.7)
    add_p(doc, "• CHƯƠNG 2: PHƯƠNG PHÁP NGHIÊN CỨU VÀ THIẾT KẾ KIẾN TRÚC HỆ THỐNG. Trình bày phương pháp luận nghiên cứu, phân tích 70 yêu cầu chức năng và các yêu cầu phi chức năng; thiết kế kiến trúc Clean Architecture 5 tầng; thiết kế chi tiết 42 bảng cơ sở dữ liệu quan hệ; thiết kế các sơ đồ luồng dữ liệu, luồng thanh toán, luồng vòng đời chế biến KDS và quy trình quản trị ca két tiền.", indent=0.7)
    add_p(doc, "• CHƯƠNG 3: HIỆN THỰC HÓA VÀ ĐÁNH GIÁ KẾT QUẢ ĐẠT ĐƯỢC. Mô tả chi tiết quá trình hiện thực hóa các phân hệ giao diện POS, KDS, BOH Admin, QR Mobile và dịch vụ backend; trình bày kết quả kiểm thử chức năng tự động với bộ 334 kịch bản xUnit (đạt tỷ lệ thành công 100%); đánh giá các chỉ số hiệu năng và thời gian đáp ứng thực tế của hệ thống.", indent=0.7)
    add_p(doc, "• KẾT LUẬN VÀ HƯỚNG PHÁT TRIỂN: Tổng kết các kết quả khoa học và thực tiễn chính đã hoàn thành, chỉ ra những hạn chế còn tồn tại và đề xuất các định hướng mở rộng nghiên cứu phát triển hệ thống trong tương lai.", indent=0.7)
    add_p(doc, "• TÀI LIỆU THAM KHẢO: Danh mục các tài liệu, giáo trình, công trình nghiên cứu và tiêu chuẩn kỹ thuật được trích dẫn theo chuẩn IEEE.", indent=0.7)

print("Module Intro completed.")
